using System.Collections.ObjectModel;using System.Windows.Input;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class BackupsViewModel:ObservableObject{readonly AgentDashboardClient client;bool loading;string? error;public ObservableCollection<BackupJobRow> Jobs{get;}=[];public ObservableCollection<BackupRow> Backups{get;}=[];public bool IsLoading{get=>loading;private set{if(Set(ref loading,value)){Raise(nameof(HasNoJobs));Raise(nameof(HasNoBackups));}}}public string? Error{get=>error;private set{if(Set(ref error,value))Raise(nameof(HasError));}}public bool HasError=>!string.IsNullOrWhiteSpace(Error);public bool HasNoJobs=>!IsLoading&&!HasError&&Jobs.Count==0;public bool HasNoBackups=>!IsLoading&&!HasError&&Backups.Count==0;public ICommand RefreshCommand{get;}public BackupsViewModel(AgentDashboardClient c){client=c;RefreshCommand=new AsyncCommand(LoadAsync);}public async Task LoadAsync(){IsLoading=true;Error=null;try{var x=await client.BackupsAsync();Jobs.Clear();Backups.Clear();if(x is null)return;foreach(var j in x.Jobs)Jobs.Add(new(j.DatabaseName,Status(j.Status),j.Stage,j.Percent is null?"—":$"{j.Percent}%",PersianDateFormatter.Format(j.UpdatedAtUtc)));foreach(var b in x.Backups)Backups.Add(new(b.DatabaseName,Status(b.Status),Verify(b.VerificationStatus),Size(b.SizeBytes),PersianDateFormatter.Format(b.StartedAtUtc),b.LocalFileAvailable?"موجود":"ناموجود",b.Error));}catch(Exception ex){Error=ex.Message;}finally{IsLoading=false;Raise(nameof(HasNoJobs));Raise(nameof(HasNoBackups));}}static string Status(int s)=>s switch{2=>"موفق",3=>"ناموفق",1=>"در حال اجرا",_=>"در صف"};static string Verify(int s)=>s switch{2=>"تأیید شده",3=>"ناموفق",1=>"در حال بررسی",_=>"—"};static string Size(long? v){if(v is null)return"—";double n=v.Value;string[]u=["B","KB","MB","GB","TB"];int i=0;while(n>=1024&&i<u.Length-1){n/=1024;i++;}return$"{n:0.#} {u[i]}";}}internal sealed record BackupJobRow(strin